/**
 * PAYLOAD of the `signal.dispatched` envelope. Topic: signals.signal.dispatched. ★★ THE FLAGSHIP event (§11 revenue-truth loop, moat (1)). Emitted by the signals service after it dispatches a ground-truth outcome to a platform conversions API (Meta CAPI web/CRM/business-messaging incl CTWA; Google Enhanced Conversions for Leads + offline adjustments). value carries the lead-quality score (or true Purchase value) so the platform optimizes for revenue truth, not junk 'lead submitted' events. event_id = hash(journey_id + ladder_step) for idempotent dedup >=90% (§11.3). Canonical field shape from Appendix A.
 */
export interface SignalDispatched {
  /**
   * Destination platform (Appendix A: meta).
   */
  platform: "meta" | "google";
  /**
   * Which conversions surface (Appendix A: capi). business_messaging keys on ctwa_clid (§11.2); ec_leads + offline_adjustment = Google quality loop (§11.3).
   */
  endpoint: "capi" | "capi_business_messaging" | "capi_crm" | "ec_leads" | "offline_conversion_adjustment";
  /**
   * The event-ladder step (§11.1): Lead | QualifiedLead | Schedule | Attended | Purchase (Appendix A: QualifiedLead). QualifiedLead/Attended are custom events.
   */
  event_name: "Lead" | "QualifiedLead" | "Schedule" | "Attended" | "Purchase";
  /**
   * The dedup event_id = hash(journey_id + ladder_step) (Appendix A event_id: 'sha256(j_+step2)'). Makes re-sends idempotent => dedup >=90% (§11.3 invariant).
   */
  dispatch_event_id: string;
  /**
   * Which hashed match keys were attached (Appendix A: [ph,fbc,ctwa_clid]). Max keys => higher EMQ (§11.3 target EMQ>=8). PII is SHA-256 normalized; raw PII never leaves (§5.4).
   *
   * @minItems 1
   */
  match_keys: [
    (
      | "em"
      | "ph"
      | "fn"
      | "ln"
      | "ct"
      | "st"
      | "zp"
      | "external_id"
      | "fbp"
      | "fbc"
      | "fbclid"
      | "ctwa_clid"
      | "gclid"
      | "wbraid"
      | "gbraid"
    ),
    ...(
      | "em"
      | "ph"
      | "fn"
      | "ln"
      | "ct"
      | "st"
      | "zp"
      | "external_id"
      | "fbp"
      | "fbc"
      | "fbclid"
      | "ctwa_clid"
      | "gclid"
      | "wbraid"
      | "gbraid"
    )[]
  ];
  /**
   * Conversion value (Appendix A: 78). On Lead = lead_score (predicted-value proxy); on Purchase = true order value. INR.
   */
  value?: number;
  /**
   * Appendix A: INR.
   */
  currency?: "INR";
  /**
   * The correlation_id (journey) this signal belongs to — ties the dispatch back to the person's funnel.
   */
  journey_ref?: string;
  /**
   * The ad the conversion is attributed to (from ctwa_clid / fbclid / gclid), form platform:ad:id.
   */
  source_ad_ref?: string;
  /**
   * source(occurred_at) -> dispatched latency in ms; SLA p95 <=15min (§11.3). For AI calls, India edge target <60s.
   */
  latency_ms?: number;
  /**
   * The dedup key used against the platform (mirrors dispatch_event_id; surfaced for the Signal Health card §11.3).
   */
  dedup_key?: string;
}
